for salah in (([80, 90], [1]), ([80], [0]), ([], [])):
    try:
        rata_rata_tertimbang(*salah)
    except ValueError:
        pass
    else:
        raise AssertionError(f"harus ValueError: {salah}")

from itertools import combinations
def periksa(tim):
    j = jadwal_round_robin(tim)
    n = len(tim)
    assert len(j) == (n - 1 if n % 2 == 0 else n), (tim, len(j))
    semua = []
    for putaran in j:
        main = [t for laga in putaran for t in laga]
        assert len(main) == len(set(main)), putaran
        assert len(main) == (n if n % 2 == 0 else n - 1), putaran
        semua += [frozenset(laga) for laga in putaran]
    assert len(semua) == len(set(semua)) == n * (n - 1) // 2
    assert set(semua) == {frozenset(p) for p in combinations(tim, 2)}
for tim in (["A", "B"], ["X", "Y", "Z"], ["7A", "7B", "7C", "7D"], [f"T{i}" for i in range(9)], [f"Kelas {i}" for i in range(12)]):
    periksa(tim)
assert jadwal_round_robin([]) == [] and jadwal_round_robin(["Sendiri"]) == []
try:
