from fractions import Fraction as F
assert bagian_waris(True, ["Ani", "Budi", "Cici"]) == {"pasangan": F(1, 4), "Ani": F(1, 4), "Budi": F(1, 4), "Cici": F(1, 4)}
assert bagian_waris(False, ["Ani", "Budi"]) == {"Ani": F(1, 2), "Budi": F(1, 2)}
assert bagian_waris(True, []) == {"pasangan": F(1)}
assert bagian_waris(False, []) == {}
assert bagian_waris(False, [{"nama": "Dedi", "keturunan": []}]) == {}
r = bagian_waris(True, ["Ani", {"nama": "Budi", "keturunan": ["Citra", "Dimas"]}])
assert r == {"pasangan": F(1, 3), "Ani": F(1, 3), "Citra": F(1, 6), "Dimas": F(1, 6)}
r = bagian_waris(False, ["A", {"nama": "B", "keturunan": ["C", {"nama": "D", "keturunan": ["E", "F"]}]}, {"nama": "G", "keturunan": []}])
assert r == {"A": F(1, 2), "C": F(1, 4), "E": F(1, 8), "F": F(1, 8)}
r = bagian_waris(True, [{"nama": "B", "keturunan": [{"nama": "C", "keturunan": []}]}, "D"])
assert r == {"pasangan": F(1, 2), "D": F(1, 2)}
r = bagian_waris(False, [{"nama": "B", "keturunan": ["C", "D", "E"]}])
assert r == {"C": F(1, 3), "D": F(1, 3), "E": F(1, 3)}
assert all(isinstance(v, F) for v in r.values()) and sum(r.values()) == 1
